 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/compiler.h>
#include <nuttx/board.h>

#include <errno.h>
#include <sched.h>
#include <syslog.h>

#ifdef CONFIG_D13X_HOME_PANEL
int home_panel_main(int argc, FAR char *argv[]);
#endif

