 * Name: board_app_initialize
 *
 * Description:
 *   应用层初始化
 *
 ****************************************************************************/

int board_app_initialize(uintptr_t arg)
{
#ifdef CONFIG_D13X_HOME_PANEL
  int pid;

  pid = task_create("home_panel", CONFIG_D13X_HOME_PANEL_PRIORITY,
                    CONFIG_D13X_HOME_PANEL_STACKSIZE,
